const BUILD = '1d608f616a';
const CACHE = 'second-life-2000';
const urlOf = (p) => new URL(p, self.registration.scope).href;
const keyOf = (p) => `${urlOf(p)}?h=${ASSETS[p]}`;
const byUrl = new Map(Object.keys(ASSETS).map((p) => [urlOf(p), p]));
const tell = async (msg) => { for (const c of await self.clients.matchAll({ includeUncontrolled: true })) c.postMessage({ sl: true, build: BUILD, ...msg }); };

async function fill() {
  const cache = await caches.open(CACHE);
  const have = new Set((await cache.keys()).map((r) => r.url));
  const all = Object.keys(ASSETS), todo = all.filter((p) => !have.has(keyOf(p)));
  let done = all.length - todo.length, last = 0, failed = 0;
  const report = (force) => { const now = Date.now(); if (force || now - last > 300) { last = now; tell({ type: 'progress', done, total: all.length }); } };
  report(true);
  const one = async (p) => {
    for (let n = 0; n < 3; n++) {
      try {
        const r = await fetch(`${urlOf(p)}?h=${ASSETS[p]}`, { cache: 'no-store' });
        if (!r.ok) throw new Error(String(r.status));
        await cache.put(keyOf(p), r); done++; report(); return;
      } catch { await new Promise((res) => setTimeout(res, 500 * (n + 1))); }
    }
    failed++;
  };
  const queue = todo.slice();
  await Promise.all(Array.from({ length: 6 }, async () => { while (queue.length) await one(queue.shift()); }));
  report(true);
  if (failed) { tell({ type: 'failed', failed }); throw new Error(`받지 못한 파일 ${failed}개`); }
}
